function moderate(button){const action=button.dataset.moderate,id=button.dataset.id,title=action==='approve'?'Одобрить публикацию':action==='reject'?'Отклонить заметку':'Снять публикацию';openDialog('РЕШЕНИЕ МОДЕРАЦИИ',`<h2>${title}?</h2><p>${action==='approve'?'Заметка станет публичной в сообществе SETKA. Автор уже отправил её на модерацию.':'Заметка не будет видна в публичной библиотеке.'}</p><label>Причина решения<textarea id="moderation-reason" rows="3" maxlength="800" placeholder="Можно добавить короткое объяснение"></textarea></label><div class="row" style="margin-top:18px"><button id="confirm-moderation" class="primary">${title}</button><button id="cancel-moderation">Отмена</button></div><p id="moderation-error" class="error" role="alert"></p>`);$('cancel-moderation').onclick=()=>dialog.close();$('confirm-moderation').onclick=async()=>{const b=$('confirm-moderation');b.disabled=true;try{const out=await api(action,{id,reason:$('moderation-reason').value},COMMUNITY_API);if(!out.ok)throw new Error('not_confirmed');communityData=null;dialog.close();await refresh();}catch(e){$('moderation-error').textContent=e.status===409?'Состояние заметки изменилось. Обновите очередь.':errorText(e);b.disabled=false;}};}
