  $('edit-experiment').onclick=()=>editExperiment(p);detail.querySelectorAll('[data-restore-plan]').forEach(b=>b.onclick=()=>{const old=revisions.find(r=>r.revision===Number(b.dataset.restorePlan));if(old)editExperiment({...old.content,id:p.id,revision:p.revision,status:'draft'},'rollback');});
