function editExperiment(plan=null,decision='edit'){
  const pid=plan?.pattern_id||'dandelion';
  openDialog('ПЛАН ЭКСПЕРИМЕНТА',`<h2>${decision==='rollback'?'Восстановить предыдущий план':plan?'Изменить план':'Новый план исследования'}</h2><form id="experiment-form"><label>Название<input id="plan-title" minlength="3" maxlength="160" required value="${esc(plan?.title||'')}" placeholder="Короткое название исследования"></label><label style="margin-top:12px">Проверяемая гипотеза<textarea id="plan-hypothesis" minlength="10" maxlength="4000" required rows="3" placeholder="Что сравниваем и какое наблюдаемое различие проверяем">${esc(plan?.hypothesis||'')}</textarea></label><div class="row" style="margin-top:12px"><label>Паттерн<select id="plan-pattern">${patterns.map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${esc(patternName(p.id))}</option>`).join('')}</select></label><label>Целевая метрика<select id="plan-metric">${['view_duration','completion','state_delta'].map(k=>`<option value="${k}" ${plan?.target_metric===k?'selected':''}>${metricName(k)}</option>`).join('')}</select></label><label>Участников минимум<input id="plan-sample" type="number" min="2" max="100000" required value="${plan?.minimum_participants||20}"></label></div><div class="grid-two" style="margin-top:16px"><label>Группа А<select id="plan-group-a"></select></label><label>Группа Б<select id="plan-group-b"></select></label></div><label style="margin-top:16px">Состояние плана<select id="plan-status">${['draft','prepared','paused','closed'].filter(k=>plan||k==='draft').map(k=>`<option value="${k}" ${plan?.status===k?'selected':''}>${planStatus(k)}</option>`).join('')}</select></label><p class="muted small" style="margin-top:16px">Сохранение создаёт новую версию плана. Оно не назначает группы и не меняет рекомендации участникам. Откат также сохраняет историю.</p><button type="submit" id="plan-save" class="primary">Сохранить ${plan?'новую версию':'черновик'}</button><p id="plan-error" role="alert" class="error"></p></form>`);
  let options=[];
  const fill=()=>{const pattern=$('plan-pattern').value;options=[{key:'base',label:'Базовая конфигурация',config:exactPattern(pattern).defaults},...data.configMetrics.filter(c=>c.pattern_id===pattern).map((c,i)=>({key:c.config_key,label:`Сохранённая конфигурация ${i+1}`,config:c.config}))];for(const [id,group] of [['plan-group-a',plan?.group_a],['plan-group-b',plan?.group_b]]){$(id).innerHTML=options.map((o,i)=>`<option value="${i}">${esc(o.label)}</option>`).join('');if(group?.config){const i=options.findIndex(o=>JSON.stringify(o.config)===JSON.stringify(group.config));if(i>=0)$(id).value=String(i);else{options.push({key:group.configKey||'recorded',label:'Конфигурация сохранённого плана',config:group.config});$(id).insertAdjacentHTML('beforeend',`<option value="${options.length-1}" selected>Конфигурация сохранённого плана</option>`);}}}};
  fill();$('plan-pattern').onchange=()=>{plan=plan?{...plan,group_a:null,group_b:null}:null;fill();};
  $('experiment-form').onsubmit=async e=>{e.preventDefault();const b=$('plan-save');b.disabled=true;$('plan-error').textContent='';const a=options[Number($('plan-group-a').value)],c=options[Number($('plan-group-b').value)];
    if($('plan-status').value==='prepared'&&JSON.stringify(a.config)===JSON.stringify(c.config)){$('plan-error').textContent='Для сравнения выберите две разные конфигурации.';b.disabled=false;return;}
    const payload={id:plan?.id||null,expectedRevision:plan?.revision||0,title:$('plan-title').value,hypothesis:$('plan-hypothesis').value,patternId:$('plan-pattern').value,metric:$('plan-metric').value,minimumParticipants:Number($('plan-sample').value),groupA:{label:'А',configKey:a.key,config:a.config},groupB:{label:'Б',configKey:c.key,config:c.config},status:$('plan-status').value,decision};
    try{const out=await api('save-experiment',payload);if(!out.ok)throw new Error('plan_save_failed');dialog.close();await refresh();openExperiment(out.item.id);}catch(err){$('plan-error').textContent=err.message==='revision_conflict'?'План уже изменён. Обновите данные перед сохранением.':'Сохранение не подтверждено. Обновите список, прежде чем повторять.';b.disabled=false;}
  };
}
function openDiagnostics(){if(!data)return;openDialog('ДОСТУП И ДИАГНОСТИКА',`<h2>Данные и синхронизация</h2><p class="muted">Проверено ${fmtDate(data.updatedAt)}. Проект приложения и админки совпадает.</p>${section('Источники данных',table(['Источник','Состояние','Записей','Обновление'],data.sources.map(s=>[esc(s.label),`<span class="${s.ok&&!s.truncated?'source-ok':'source-error'}">${s.ok?s.truncated?'Загружен частично':'Доступен':'Недоступен'}</span>`,fmtNum(s.count),esc(fmtDate(s.updatedAt))])))}${section('Что не видно серверу',data.warnings.map(w=>`<p>${esc(w.message)}</p>`).join('')+`<p>Точный путь синхронизации: пользователь входит в свой аккаунт → подтверждает действующий договор хранения → существующий модуль отправляет его личный архив. Админка читает только уже поступившие записи. Образы устройств и старые общие метки не подтверждают личность.</p>`)}${section('Тестовые физиологические записи',`<p>Исключено из реальных показателей: ${data.excludedSimulatedPhysio||0} записей тестового потока. Они явно помечены как имитация.</p>`)}${section('Зарегистрированные ошибки клиентов',data.diagnostics.length?table(['Дата','Состояние','Сборка'],data.diagnostics.map(d=>[esc(fmtDate(d.created_at)),d.online===false?'Нет подключения':'Зарегистрирована ошибка синхронизации',esc(d.build)])):empty('Ошибки не зарегистрированы','Пустой журнал не доказывает, что на устройствах ошибок нет.'))}${section('Доступ и сохранность',`<p>Используется существующий административный ключ. Сервер проверяет его перед чтением. Ключи и личные данные не включены в опубликованный код.</p><p>Новая админка не изменяет сроки хранения, не удаляет Replay и не меняет права таблиц. Управление существующими доступами остаётся в прежней полной админке.</p><a class="quiet-link" href="standalone-admin-v34.html" target="_blank" rel="noopener">Открыть технический контур прежней админки ↗</a>`)}${technical({version:VERSION,projectId:data.projectId,updatedAt:data.updatedAt,rendererVersion,sources:data.sources})}`);}

function patternNamingSection(id){
 const item=(data.patternCatalog||[]).find(x=>x.pattern_id===id),history=(data.patternNameHistory||[]).filter(x=>x.pattern_id===id).sort((a,b)=>b.revision-a.revision);
 return section('Название в приложении',item?`<p>Это название используется в админке и на фронте. Изменение не меняет сам паттерн, его настройки или исторические слепки.</p>${btn('Изменить название','rename-pattern',id,'primary')}${history.length?table(['Версия','Название','Дата'],history.map(x=>[x.revision,esc(x.title),esc(fmtDate(x.created_at))])):''}`:empty('Каталог названий не загружен','Обновите данные перед изменением названия.'));
}
function renamePattern(id){
 const current=(data.patternCatalog||[]).find(x=>x.pattern_id===id);if(!current)return;
 const old=(data.patternNameHistory||[]).filter(x=>x.pattern_id===id&&x.revision!==current.revision).sort((a,b)=>b.revision-a.revision);
 openDialog('НАЗВАНИЕ ПАТТЕРНА',`<h2>Изменить название</h2><form id="rename-form"><label>Название<input id="pattern-title" required maxlength="80" value="${esc(current.title)}"></label>${old.length?`<label style="margin-top:16px">Восстановить прежнее название<select id="previous-title"><option value="">Выбрать…</option>${old.map(x=>`<option value="${x.revision}">${esc(x.title)}</option>`).join('')}</select></label>`:''}<p class="muted small">После сохранения открытые копии фронта обновят название в течение 30 секунд. Восстановление прежнего названия тоже сохраняет новую версию истории.</p><button id="rename-save" class="primary" type="submit">Сохранить для всех</button><p id="rename-error" class="error" role="alert"></p></form>`);
 if($('previous-title'))$('previous-title').onchange=()=>{const x=old.find(x=>x.revision===Number($('previous-title').value));if(x)$('pattern-title').value=x.title};
 $('rename-form').onsubmit=async e=>{e.preventDefault();const save=$('rename-save'),error=$('rename-error');save.disabled=true;try{await api('rename-pattern',{patternId:id,title:$('pattern-title').value.trim(),expectedRevision:current.revision});dialog.close();await refresh();openPattern(id);}catch(e){error.textContent=e.message==='revision_conflict'?'Название уже изменено. Обновите данные перед сохранением.':'Сохранение не подтверждено. Обновите каталог перед повторной попыткой.';save.disabled=false;}};
}
function participantsPage(view){
 if(participantsTab==='invites')invitesPage();else peoplePage(view);
 const tabs=document.createElement('div');tabs.className='tabs';tabs.innerHTML=`<button id="people-tab" class="${participantsTab==='people'?'selected':''}">Участники</button><button id="invites-tab" class="${participantsTab==='invites'?'selected':''}">Пригласительные ID и рефералы</button>`;$('content').prepend(tabs);
 $('people-tab').onclick=()=>{participantsTab='people';render()};$('invites-tab').onclick=()=>{participantsTab='invites';render()};
}
function invitesPage(){
 const source=data.sources.find(x=>x.key==='issuedInvites');
 if(!source?.ok){$('content').innerHTML=empty('Журнал приглашений недоступен','Отсутствие загрузки не означает, что ID не выдавались. Обновите данные.');return;}
 const items=data.issuedInvites||[],batches=data.inviteBatches||[];
 $('content').innerHTML=`<div class="row between"><p class="muted small">Журнал выдачи за всё время. Одноразовый код и постоянный ID аккаунта — разные вещи. Код принимается только один раз.</p>${btn('Создать ID или пакет','invite-create','new','primary')}</div><div class="mini-stats"><div><b>${items.length}</b><span>Выдано ID${source.truncated?' · частичный журнал':''}</span></div><div><b>${items.filter(x=>x.consumed_at).length}</b><span>Приглашений принято</span></div><div><b>${items.filter(x=>x.password_set_at).length}</b><span>Аккаунтов создано</span></div></div><div class="tools"><input id="invite-search" type="search" placeholder="ID, название пакета или автор" aria-label="Поиск приглашений"></div><article class="card" id="invite-results"></article>${section('Пакеты выдачи',batches.length?table(['Название','Автор','Дата','Создано / запрошено','Аккаунты'],batches.map(b=>{const rows=items.filter(x=>x.batch_id===b.id);return [esc(b.label),b.issued_by_tester_id?personButton(`account:${b.issued_by_tester_id}`):'Администратор',esc(fmtDate(b.created_at)),`${rows.length} / ${b.requested_count}`,rows.filter(x=>x.password_set_at).length]})):empty('Пакетов пока нет','Ранние ID без пакета остаются в общем журнале.'))}`;
 const show=()=>{const q=$('invite-search').value.trim().toLowerCase(),rows=items.filter(x=>`${x.tester_id} ${x.invite_label||''} ${x.issued_by_tester_id||''}`.toLowerCase().includes(q));if(rows.length)paged($('invite-results'),rows,['ID','Название','Кто выдал','Создан','Состояние','Участник'],x=>[esc(x.tester_id),esc(x.invite_label||'Без названия'),x.issued_by_tester_id?personButton(`account:${x.issued_by_tester_id}`):x.admin_key_id?'Администратор':'Автор ранней выдачи не записан',esc(fmtDate(x.created_at)),esc(inviteState(x)),x.password_set_at?personButton(`account:${x.tester_id}`):'Аккаунт ещё не создан']);else $('invite-results').innerHTML=empty('Приглашений не найдено','Измените поиск или создайте новый пакет.');};$('invite-search').oninput=show;show();
}
function referralSection(participantId){
 if(!data.sources.some(x=>x.key==='issuedInvites'&&x.ok))return section('Приглашения и рефералы',empty('Журнал приглашений не загружен','Количество выданных ID и связи пока не подтверждены. Обновите данные.'));
 if(!participantId.startsWith('account:'))return '';const tid=participantId.slice(8),issued=(data.issuedInvites||[]).filter(x=>x.issued_by_tester_id===tid),own=(data.issuedInvites||[]).find(x=>x.tester_id===tid);
 return section('Приглашения и рефералы',`${own?.issued_by_tester_id?`<p>Пригласил ${personButton(`account:${own.issued_by_tester_id}`)}. Название: ${esc(own.invite_label||'Без названия')}.</p>`:''}<p>Выдано ID: ${issued.length}. Принято приглашений: ${issued.filter(x=>x.consumed_at).length}. Создано аккаунтов: ${issued.filter(x=>x.password_set_at).length}.</p>${issued.length?table(['ID','Название','Состояние','Участник'],issued.map(x=>[esc(x.tester_id),esc(x.invite_label||'Без названия'),esc(inviteState(x)),x.password_set_at?personButton(`account:${x.tester_id}`):'Ещё не создан'])):'<p class="muted">Выдача этим аккаунтом пока не зарегистрирована.</p>'}`);
}
function createInvites(){
 openDialog('ВЫДАЧА ПРИГЛАСИТЕЛЬНЫХ ID',`<h2>Новый ID или пакет</h2><form id="invite-form"><label>Название или назначение<input id="invite-label" maxlength="120" required placeholder="Например: рекламная кампания в октябре"></label><label style="margin-top:16px">Количество ID<input id="invite-count" type="number" min="1" step="1" value="1" required></label><p class="muted small">Большие пакеты создаются порциями по 100. Скопируйте или скачайте коды до закрытия окна: на сервере сохраняются только их хэши.</p><button id="invite-generate" class="primary" type="submit">Создать</button><p id="invite-progress" role="status"></p><p id="invite-error" class="error" role="alert"></p></form><div id="invite-copy-tools" hidden><button id="invite-copy">Скопировать все коды</button><button id="invite-download">Скачать список</button></div><pre id="issued-codes" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre>`);
 let generated=[],batchId=null;
 $('invite-copy').onclick=async()=>{try{await navigator.clipboard.writeText(generated.map(x=>`${x.testerId}\t${x.code}`).join('\n'));$('invite-progress').textContent='Коды скопированы'}catch(_){$('invite-error').textContent='Копирование не удалось. Скачайте список или выделите коды.'}};
 $('invite-download').onclick=()=>{const url=URL.createObjectURL(new Blob([generated.map(x=>`${x.testerId}\t${x.code}`).join('\n')],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='setka-invite-codes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 $('invite-form').onsubmit=async e=>{e.preventDefault();const form=$('invite-form'),go=$('invite-generate'),progress=$('invite-progress'),error=$('invite-error'),label=$('invite-label').value.trim(),total=Number($('invite-count').value),codes=$('issued-codes'),tools=$('invite-copy-tools');if(!label||label.length>120||!Number.isInteger(total)||total<1||total>2147483647){error.textContent='Введите название и целое количество больше нуля.';return}go.disabled=true;generated=[];batchId=null;error.textContent='';codes.textContent='';tools.hidden=true;
  try{while(generated.length<total&&form.isConnected){const out=await api('issue-invites',{label,count:Math.min(100,total-generated.length),requestedCount:total,batchId,requestId:crypto.randomUUID()});batchId=out.batchId;generated.push(...out.items);progress.textContent=`Создано ${generated.length} из ${total}. Коды доступны до закрытия окна.`;codes.textContent=generated.map(x=>`${x.testerId}\t${x.code}`).join('\n');tools.hidden=false;}}
  catch(_){error.textContent='Выдача прервалась. Скопируйте полученные коды и обновите журнал перед новой выдачей.';}finally{go.disabled=false;await refresh();}
 };
}

$('login-form').addEventListener('submit',login);$('logout').onclick=logout;$('refresh').onclick=()=>refresh();$('diagnostics-button').onclick=openDiagnostics;$('close-dialog').onclick=()=>dialog.close();// A queued close event may arrive after a fast save has opened the next card.
dialog.addEventListener('close',()=>{if(dialog.open)return;player?.stop();player=null;detail.replaceChildren();startPreviews();});
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('period').onchange=setPeriod;$('from-date').onchange=setPeriod;$('to-date').onchange=setPeriod;$('scope').onchange=()=>{filters.scope=$('scope').value;render();};
motion.addEventListener?.('change',startPreviews);
window.addEventListener('setka:renderer-ready',()=>{if(data)render()});
document.addEventListener('visibilitychange',()=>{if(document.hidden){player?.stop();stopPreviews();}else{startPreviews();if(data&&Date.now()-time(data.updatedAt)>60000)refresh();}});
setInterval(()=>{if(adminKey&&!document.hidden&&!dialog.open)refresh();},60000);
const route=location.hash.slice(1);if(NAV[route])page=route;
const savedAccess=credentialStore.load();adminKey=ownerTicket?'':entryAccess.key||savedAccess.key;
$('remember').checked=entryAccess.consumed?true:savedAccess.remember;
if(ownerTicket){$('key').hidden=true;$('key').required=false;$('key-label').hidden=true;$('login-error').textContent='Доступ владельца подготовлен. Нажмите «Открыть исследования».';}
else if(adminKey)login();
navigate(page);
